def fetch_og_card(url: str) -> dict[str, str] | None:
    """`url`'s link card (og_card), or None when the page can't be read.
    Sent as SELF_FETCH_USER_AGENT: most of these are Civitas's own pages,
    and the logs should say it was the app reading itself."""
    import ipaddress, socket
    from urllib.parse import urlsplit
    _parts = urlsplit(str(url))
    if _parts.scheme.lower() == "file":
        raise ValueError("refusing file:// URL")
    try:
        _infos = socket.getaddrinfo(_parts.hostname, None) if _parts.hostname else []
    except OSError:
        _infos = []
    for _info in _infos:
        _addr = ipaddress.ip_address(_info[4][0])
        if (_addr.is_private or _addr.is_loopback or _addr.is_link_local
                or _addr.is_reserved or _addr.is_multicast or _addr.is_unspecified):
            raise ValueError("refusing non-public destination")
    try:
        resp = httpx.get(url, timeout=10, follow_redirects=True, headers={"User-Agent": SELF_FETCH_USER_AGENT})
        resp.raise_for_status()
    except Exception:
        logger.debug("Link card fetch failed for %s", url)
        return None
    return og_card(resp.text)
